private async void ClearCache_Click(object sender, RoutedEventArgs e)
{
    var cacheDir = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "PZWorkshopDownloader", "steamcmd", "workshop", "content", "108600");

    if (!Directory.Exists(cacheDir))
    {
        MessageBox.Show("No cached workshop mods found at the expected location.", "Cache Empty");
        AppendLog("Clear cache clicked — no cached content exists.");
        return;
    }

    var confirm = MessageBox.Show(
        $"This will permanently delete all cached Workshop mod content in:\n\n{cacheDir}\n\n" +
        "The installed mods list and SteamCMD itself are NOT affected.\n" +
        "Downloaded mods can be re-fetched at any time.\n\nAre you sure?",
        "Clear Cached Mods", MessageBoxButton.YesNo, MessageBoxImage.Warning);

    if (confirm == MessageBoxResult.No) return;

    try
    {
        foreach (var dir in Directory.GetDirectories(cacheDir))
            Directory.Delete(dir, recursive: true);
        AppendLog("Cached workshop mod contents cleared.");
        var count = Directory.GetDirectories(cacheDir).Length;
        StatusText.Text = "Cache cleared.";
        MessageBox.Show($"Deleted content directories.\n{count} subdirectory(ies) remain.", "Done");
    }
    catch (Exception ex)
    {
        AppendLog($"Failed to clear cache: {ex.Message}", "ERROR");
        MessageBox.Show($"Could not delete cached content:\n{ex.Message}", "Error", MessageBoxButton.OK, MessageBoxImage.Error);
    }
}

