        $"This will permanently delete all locally cached Workshop mod data:\n\n{SteamCmdService.GetContentPath("")}.*\n\n" +
        "Installed mods and SteamCMD itself are NOT affected.\n" +
        "Downloaded mods can be re-fetched at any time.\n\nAre you sure?",
        "Clear Cached Mods", MessageBoxButton.YesNo, MessageBoxImage.Warning);

    if (confirm == MessageBoxResult.No) return;

    try
    {
        foreach (var di in new DirectoryInfo(contentDir).EnumerateDirectories().ToArray())
            di.Delete(true);
        AppendLog("Cached workshop mod contents cleared.");
        StatusText.Text = "Cached mods cleared.";
    }
    }
    catch (Exception ex)
    {
        AppendLog($"Failed to clear cache: {ex.Message}", "ERROR");
        MessageBox.Show($"Could not delete cached content:\n{ex.Message}", "Error", MessageBoxButton.OK, MessageBoxImage.Error);
    }
}

